nt-jp1500.css:
/* Tarjeta CJ (mazo inicial jp1500) — hermana del diseño B-v2 de inmersión. Shadow DOM aislado:
   todo scopeado a .card (claro) y .card.nightMode (oscuro) con HEX; aquí NO existen las variables
   del portal. */
.card {
	/* Fuente ORIGINAL del mazo 1500 (gótica), restaurada por David (6-jul): la palabra que se estudia
	   vuelve a verse como antes de la tarjeta CJ (NO mincho). Inmersión conserva su mincho. */
	font-family: "ヒラギノ角ゴ Pro W3", "Hiragino Kaku Gothic Pro", "Noto Sans JP", "Noto Sans CJK JP", Osaka, "メイリオ", Meiryo, "ＭＳ Ｐゴシック", "MS PGothic", "MS UI Gothic", sans-serif;
	font-size: 16px;
	line-height: 1.5;
	text-align: center; /* TODO centrado (David, 6-jul): el ojo baja recto, sin saltar de izq. a der. */
	color: #2a2520;
}
.card.nightMode { color: #ece3d6; }

/* ── Anverso: palabra centrada (fuente original del mazo, heredada de .card) + frase con la palabra en teja ── */
.card .cj-front { padding: 44px 20px 40px; text-align: center; }
.card .cj-front-word {
	font-size: 48px; font-weight: 600; line-height: 1.2;
}
.card .cj-front-sent { margin-top: 18px; font-size: 21px; line-height: 1.8; }
.card .cj-front-sent b { color: #a23a22; font-weight: 800; }
.card.nightMode .cj-front-sent b { color: #f0a088; }
.card .cj-front-hint { margin-top: 24px; color: #6e665a; font-size: 12.5px; }
.card.nightMode .cj-front-hint { color: #b0a595; }

/* ── Reverso ── (position:relative → ancla el badge de frecuencia en la esquina) */
.card .cj-back { padding: 18px 18px 16px; display: grid; gap: 14px; position: relative; }
.card .cj-word {
	font-size: 40px; font-weight: 600; line-height: 1.25;
}
.card .cj-word ruby rt { font-size: .42em; color: #6e665a; font-weight: 500; letter-spacing: .06em; user-select: none; }
.card.nightMode .cj-word ruby rt { color: #b0a595; }

/* Fila meta (pitch o kana + botón Palabra a su derecha). El texto (.cj-meta-t) es un inline-block
   centrado (text-align) y el botón cuelga en absoluto a su derecha, así que NO lo desplaza. El texto
   reserva 80px a los lados (max-width) para que el botón nunca se recorte ni descentre. Si la nota no
   trae NADA, la plantilla emite la meta vacía y :empty la esconde entera — sin huecos. */
.card .cj-meta { text-align: center; }
.card .cj-meta:empty { display: none; }
.card .cj-meta-t { position: relative; display: inline-flex; gap: 8px; align-items: center; justify-content: center; flex-wrap: wrap; max-width: calc(100% - 80px); }
.card .cj-kana { font-size: 17px; color: #6e665a; letter-spacing: .04em; }
.card.nightMode .cj-kana { color: #b0a595; }
/* Dibujo NHK del acento (viene YA montado en el campo, con estilos inline que heredan currentColor):
   basta darle color teja para que katakana y línea de caída salgan en teja, en claro y en oscuro. */
.card .cj-pitch { font-size: 17.5px; line-height: 1.4; color: #a23a22; }
.card.nightMode .cj-pitch { color: #f0a088; }

/* Chip Top N de frecuencia (índigo): BADGE anclado en la esquina superior derecha, fuera del flujo
   centrado (como el de la tarjeta CJ de inmersión). La base .cj-chip da la forma de píldora. */
.card .cj-chip {
	display: inline-block; font-size: 11px; font-weight: 800; border-radius: 999px; padding: 2px 9px;
	background: #f8e4db; color: #a23a22; letter-spacing: .03em;
}
.card.nightMode .cj-chip { background: rgba(232,118,92,.18); color: #f0a088; }
.card .cj-chip-freq { position: absolute; top: 10px; right: 12px; z-index: 1; background: #e7e6f4; color: #2e2e78; }
.card.nightMode .cj-chip-freq { background: rgba(109,107,214,.2); color: #b6b4f0; }

/* Botón de audio COMPACTO: el <a class="srs-audio"> que genera finalizeMedia, como botoncito redondo
   con un ▶ (sin la etiqueta "Palabra"/"Frase": una píldora ancha no cabe a la derecha del texto sin
   desplazarlo — el contexto ya dice cuál es: junto a la lectura=palabra, junto a la frase=frase). */
.card .srs-audio {
	display: inline-flex; align-items: center; justify-content: center; width: 26px; height: 26px;
	border: 1px solid #d8cdb8; background: #f0eadb; border-radius: 999px; font-size: 0;
	cursor: pointer; user-select: none; vertical-align: middle; text-decoration: none;
	-webkit-tap-highlight-color: transparent;
}
.card .srs-audio::before { content: "▶"; font-size: 9px; color: #d45a3b; line-height: 1; margin-left: 1px; }
.card.nightMode .srs-audio { border-color: #4b3e30; background: #2d251c; }
.card.nightMode .srs-audio::before { color: #e8765c; }
/* Botones de audio a la DERECHA de su texto SIN desplazarlo: absolutos al borde derecho del propio
   texto (cj-meta-t/cj-sent-t son position:relative), fuera del flujo → el texto sigue perfectamente
   centrado sea cual sea su longitud (David, 6-jul). El texto reserva sitio a la derecha (max-width). */
.card .cj-audio-palabra, .card .cj-audio-frase { position: absolute; left: 100%; top: 50%; transform: translateY(-50%); margin-left: 8px; }

/* Definición (el significado = la respuesta): centrada y GRANDE para leerla de un vistazo (David, 6-jul).
   Sin la "regla de tinta" a la izquierda (un borde izquierdo desalinea la lectura centrada). */
.card .cj-def { font-size: 20px; }

/* Frase con furigana y la palabra en negrita acentuada; el botón Frase cuelga en absoluto a la derecha
   del texto (.cj-sent-t inline-block centrado, position:relative) SIN descentrar la frase. La lectura
   (rt) queda gris discreto aunque vaya en el <b> teja. */
.card .cj-sent { text-align: center; font-size: 20px; line-height: 1.9; }
.card .cj-sent-t { position: relative; display: inline-block; max-width: calc(100% - 80px); }
.card .cj-sent b { color: #a23a22; font-weight: 800; }
.card.nightMode .cj-sent b { color: #f0a088; }
.card .cj-sent rt { color: #6e665a; font-weight: 500; user-select: none; }
.card.nightMode .cj-sent rt { color: #b0a595; }

/* Plegable discreto (Traducción de la frase / Notas de acento): CERRADO por decisión de David —
   no se ve hasta tocar. El teclado del summary lo engancha SrsCardView. */
.card .cj-fold summary {
	cursor: pointer; width: fit-content; margin: 0 auto; color: #6e665a; font-size: 12.5px; font-weight: 700;
	letter-spacing: .03em; user-select: none;
}
.card .cj-fold summary:hover { color: #a23a22; }
.card.nightMode .cj-fold summary { color: #b0a595; }
.card.nightMode .cj-fold summary:hover { color: #f0a088; }
.card .cj-fold-body { margin-top: 6px; font-size: 14.5px; line-height: 1.6; }

/* Ilustración (Irasutoya) NO a ancho completo: centrada y contenida, AMPLIABLE (el lightbox lo
   engancha SrsCardView sobre .cj-zoomable). El tope img 300×250 del CSS base del componente se
   queda; aquí solo se ajusta el encuadre de este notetype. */
.card .cj-figure { margin: 0; }
.card .cj-zoomable img {
	display: block; margin: 0 auto; max-width: 100%; max-height: 240px; width: auto; height: auto;
	border-radius: 10px; cursor: zoom-in;
}

/* Nota del autor (solo ~50 notas la traen): bloque discreto gris, centrado y algo más estrecho para
   que se lea como un aparte (sin la regla izquierda, que rompería el centrado). */
.card .cj-note { font-size: 13.5px; line-height: 1.6; color: #6e665a; max-width: 30em; margin: 0 auto; }
.card.nightMode .cj-note { color: #b0a595; }
